SELECT CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, SORT_ARRAY(COLLECT_SET(s.status)) AS status_list FROM shipments s INNER JOIN orders o ON s.order_id = o.id WHERE s.status = 'LOST' GROUP BY CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY order_cohort DESC LIMIT 5
